import {find,isLocked,clone} from '../document/model.js';
import {currentMesh,editMesh} from '../scene/mesh-edit.js';
import {readRecentColours} from './object-colour.js';
export function showMeshColour(a){
 const n=find(a.doc,a.selected[0]);if(!n?.mesh||isLocked(a.doc,n.id))return;
 a.pause();a.properties.flush();const index=Math.min(a.activeMesh||0,currentMesh(n,a.time).points.length-1),initial=currentMesh(n,a.time).points[index].color;
 const palette=['#ffffff','#000000','#ff625f','#ffb84d','#ffe066','#65d49a','#59cbe8','#6477eb','#b87ee8','#ed85b2'];let recent=[];try{recent=readRecentColours(localStorage);}catch{}if(!recent.length)recent=a.recentColours||[];const clear=()=>{const preview={...a.appearancePreview?.get(n.id)};delete preview.mesh;if(Object.keys(preview).length)a.appearancePreview.set(n.id,preview);else a.appearancePreview?.delete(n.id);a.renderStage();};
 const d=a.dialog('Mesh point '+(index+1)+' colour',`<form><p>Choose a swatch, adjust the sliders, or enter a hex colour.</p><div class="mesh-palette">${palette.map(c=>`<button type="button" data-swatch="${c}" aria-label="Colour ${c}" style="background:${c};width:44px;height:44px"></button>`).join('')}</div><div data-colour-preview style="height:48px;margin:12px 0;border-radius:8px;background:${initial}"></div>${['Red','Green','Blue'].map((c,i)=>`<label>${c}<input aria-label="${c}" data-channel="${i}" type="range" min="0" max="255" value="${parseInt(initial.slice(1+i*2,3+i*2),16)}"></label>`).join('')}<label>Hex colour<input name="colour" aria-label="Hex colour" value="${initial}" pattern="#[0-9a-fA-F]{6}" required></label><div class="dialog-actions"><button type="button" data-close>Cancel</button><button type="submit" class="primary">Apply colour</button></div></form>`,(form,dialog)=>{const color=form.get('colour');if(!/^#[0-9a-f]{6}$/i.test(color))throw Error('Enter six hex digits after #.');clear();const current=find(a.doc,n.id);if(!current?.mesh||isLocked(a.doc,current.id))return dialog.close();a.mutate('Mesh point colour',()=>editMesh(current,a.time,m=>{m.points[index].color=color;return m;}));a.rememberColor(color);dialog.close();},{modal:false});d.classList.add('object-colour-dialog');d.addEventListener('close',clear,{once:true});
 d.querySelector('.mesh-palette').insertAdjacentHTML('beforebegin',`<h3>Last 10 colours</h3><div class="mesh-palette">${recent.length?recent.slice(0,10).map(c=>`<button type="button" data-swatch="${c}" aria-label="Recent colour ${c}" style="background:${c};width:44px;height:44px"></button>`).join(''):'<small>Applied colours appear here.</small>'}</div><h3>Swatches</h3>`);
 const channels=[...d.querySelectorAll('[data-channel]')],hex=d.querySelector('[name=colour]'),preview=d.querySelector('[data-colour-preview]');
 const update=color=>{const current=find(a.doc,n.id);if(current?.mesh){const mesh=clone(currentMesh(current,a.time));mesh.points[index].color=color;a.appearancePreview??=new Map();a.appearancePreview.set(n.id,{...a.appearancePreview.get(n.id),mesh});a.renderStage();}hex.value=color;preview.style.background=color;channels.forEach((el,i)=>el.value=parseInt(color.slice(1+i*2,3+i*2),16));};
 d.querySelectorAll('[data-swatch]').forEach(el=>el.onclick=()=>update(el.dataset.swatch));channels.forEach(el=>el.oninput=()=>update('#'+channels.map(x=>Number(x.value).toString(16).padStart(2,'0')).join('')));hex.oninput=()=>{if(/^#[0-9a-f]{6}$/i.test(hex.value))update(hex.value);};
}
